def looks_degenerate(text: str) -> bool:
    data = text.encode("utf-8")
    if len(data) > 1500 and len(zlib.compress(data)) / len(data) < 0.2:
        return True
    lines = [l.strip() for l in text.splitlines() if len(l.strip()) > 10]
    return bool(lines) and Counter(lines).most_common(1)[0][1] > 6

