def charge_text(charge: int) -> str:
    """0 → '', 1 → '⁺', -1 → '⁻', 2 → '²⁺', -2 → '²⁻'."""
    if charge == 0:
        return ""
    size = "" if abs(charge) == 1 else str(abs(charge)).translate(_SUPERSCRIPT)
    return size + ("⁺" if charge > 0 else "⁻")

function labMakeChainable(el) {
  for (const name of LAB_CHAINABLE) {
    const method = el[name];
    if (typeof method !== "function") continue;
    el[name] = function (...args) {
      const result = method.apply(el, args);
      return result === undefined ? el : result;
    };
  }
  return el;
}

def shells(z: int) -> list[int]:
    """Class 9 rule (2, 8, 8, 2): Na (11) → [2, 8, 1]."""
    out, left = [], z
    for capacity in (2, 8, 8, 2):
        if left <= 0:
            break
        out.append(min(capacity, left))
        left -= out[-1]
    return out

